head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil55230";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — completeYn

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil55230.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_delete", fn: function(){ return (!(String(((dma_stockDutyVO.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "stockDutyVO.prtdepoId"); })())) == null ? '' : ((dma_stockDutyVO.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "stockDutyVO.prtdepoId"); })()))).length === 0)); } }, { id: "btn_cancel", fn: function(){ return ((String(((dma_pageContext.get("completeYn") ?? "")) == null ? '' : ((dma_pageContext.get("completeYn") ?? ""))).length === 0)); } }, { id: "c_otherwise_102", fn: function(){ return (!(((String(((dma_pageContext.get("completeYn") ?? "")) == null ? '' : ((dma_pageContext.get("completeYn") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55230.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_onclick
 * @description ipt_stkoptDutyTotGrntShrs 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55230.ipt_stkoptDutyTotGrntShrs_onclick' }); }
};

/**
 * @method
 * @name ipt_stkoptDutyTotGrntShrs_onkeyup
 * @description ipt_stkoptDutyTotGrntShrs 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_stkoptDutyTotGrntShrs_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55230.ipt_stkoptDutyTotGrntShrs_onkeyup' }); }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function(e){
    try {
        await scwin.deleteRegisterReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55230.btn_delete_onclick' }); }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancel_onclick = function(e){
    try {
        scwin.cancel()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55230.btn_cancel_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55230.btn_close_onclick' }); }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function(e){
    try {
        await scwin.register()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil55230.btn_register_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/listInvstg/preStockDutyPopup.do",
        ref: "dma_registerReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/listInvstg/preStockDutyPopup.do",
        ref: "dma_deleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    form = (document.stockForm || { elements: [] });
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    if (($c.util.getComponent('ipt_nm').getValue() == null ? '' : String($c.util.getComponent('ipt_nm').getValue())) === '') {
        await $c.win.alert("성명/명칭을 입력하십시요.");
        $c.util.getComponent("ipt_nm").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_encrypResdbzRegNo').getValue() == null ? '' : String($c.util.getComponent('ipt_encrypResdbzRegNo').getValue())) === '') {
        await $c.win.alert("생년월일/사업자번호를 입력하십시요.");
        $c.util.getComponent("ipt_encrypResdbzRegNo").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyResolDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyResolDd').getValue())) === '') {
        await $c.win.alert("부여결의일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyResolDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('ipt_stkoptDutyTotGrntShrs').getValue() == null ? '' : String($c.util.getComponent('ipt_stkoptDutyTotGrntShrs').getValue())) === '') {
        await $c.win.alert("총 부여주식수를 입력하십시요.");
        $c.util.getComponent("ipt_stkoptDutyTotGrntShrs").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue())) === '') {
        await $c.win.alert("행사기간 시작일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyExerStartDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue())) === '') {
        await $c.win.alert("행사기간 만료일을 입력하십시요.");
        $c.util.getComponent("cal_stkoptDutyExerEndDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue())) !== '' && ($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue())) !== '') {
        if ($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue()> $c.util.getComponent('cal_stkoptDutyExerEndDd').getValue()) {
            await $c.win.alert("행사기간 시작일이 행사기간 만료일보다 이후 일자 입니다.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        }
    }
    if (($c.util.getComponent('cal_prtdepoEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_prtdepoEndDd').getValue())) === '') {
        await $c.win.alert("의무보유기간 만료일을 입력하십시요.");
        $c.util.getComponent("cal_prtdepoEndDd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
        return false;
    }
    if (!scwin.checkDate($c.util.getComponent('cal_stkoptDutyResolDd').getValue())) {
        await $c.win.alert("부여결의일 날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.");
        return false;
    }
    if (!scwin.checkDate($c.util.getComponent('cal_stkoptDutyExerStartDd').getValue()) || !scwin.checkDate($c.util.getComponent('cal_stkoptDutyExerEndDd').getValue())) {
        await $c.win.alert("행사기간 날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.");
        return false;
    }
    if (!scwin.checkDate($c.util.getComponent('cal_prtdepoEndDd').getValue())) {
        await $c.win.alert("의무보유기간 날짜 형식이 잘못 되었습니다. 확인 후 수정해 주세요.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const opener = scwin.openerScwin();
    if (await scwin.validate()) {
        if ($c.util.getComponent('dma_registerReq').get('prtdepoId') === '') {
            (document.stockForm || { elements: [] }).target = 'stockDutyWin';
            (document.stockForm || { elements: [] }).action = "preStockDutyPopup.do";
            $c.util.getComponent('dma_registerReq').set('method', "insertStockDuty");
            await scwin.tx_fn_register();
        } else {
            (document.stockForm || { elements: [] }).target = 'stockDutyWin';
            (document.stockForm || { elements: [] }).action = "preStockDutyPopup.do";
            $c.util.getComponent('dma_registerReq').set('method', "updateStockDuty");
            if (await $c.win.confirm("주식매수선택권을 수정 하시겠습니까?")) {
                await scwin.tx_fn_register();
            }
        }
    }
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function () {
    const opener = scwin.openerScwin();
    (document.stockForm || { elements: [] }).target = 'stockDutyWin';
    (document.stockForm || { elements: [] }).action = "preStockDutyPopup.do";
    $c.util.getComponent('dma_registerReq').set('method', "deleteStockDuty");
    if (await $c.win.confirm("주식매수선택권을 삭제 하시겠습니까?")) {
        await scwin.tx_fn_delete();
        opener.calcelYn = 'N';
    }
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'Y';
    $c.win.closePopup();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'N';
    $c.win.closePopup();
};

/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.checkDate = function (val) {
    if (val.length === 0) {
        return true;
    }
    if (val.length !== 8) {
        return false;
    }
    const year = val.substring(0, 4);
    const month = val.substring(4, 6);
    const day = val.substring(6, 8);
    if (month > 12 || month < 1) {
        return false;
    }
    if (month === 2 || month === 02) {
        if (day > 29 || day < 1) {
            return false;
        }
    } else {
        if (month === 1 || month === 3 || month === 5 || month === 7 || month === 8 || month === 10 || month === 12) {
            if (day > 31 || day < 1) {
                return false;
            }
        } else {
            if (month === 4 || month === 6 || month === 9 || month === 11) {
                if (day > 30 || day < 1) {
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
